// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.documentimport timber.log.Timberimport com.roshan.persona.vision.ocr.BusinessCardimport com.roshan.persona.vision.ocr.GovernmentIdimport com.roshan.persona.vision.ocr.GovernmentIdTypeimport com.roshan.persona.vision.ocr.Invoiceimport com.roshan.persona.vision.ocr.OcrBlockimport com.roshan.persona.vision.ocr.OcrFieldimport com.roshan.persona.vision.ocr.OcrFieldTypeimport com.roshan.persona.vision.ocr.Receiptimport com.roshan.persona.vision.ocr.ReceiptItemimport com.roshan.persona.vision.ocr.StructuredDocumentimport com.roshan.persona.vision.ocr.PrescriptionScanner/** * NOUS — Structured Document Parsers (Module 6 v4 — Step 6.5). * * Full implementations of the document parsers that were stubbed in Step 6.2. * Each parser extracts structured data from OCR text + extracted fields. * * ## Parsers * *  - [ReceiptParser] — extracts merchant, items, totals, payment method *  - [BusinessCardParser] — extracts name, title, company, phone, email *  - [GovernmentIdParser] — extracts Aadhaar/PAN (masked, per privacy) *  - [InvoiceParser] — extracts invoice number, vendor, GSTIN, line items * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - [GovernmentIdParser] ALWAYS masks the ID number before returning. *    Aadhaar: "XXXX-XXXX-1234" (only last 4 digits visible) *    PAN: "ABCDE***4F" (only first 5 + last char visible) *  - Raw image is cryptographically shredded (DoD 5220.22-M) within 60s of scan. *  - The masked [GovernmentId] is stored in encrypted Memory (Module 3). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.5: DocumentScannerEngine</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. RECEIPT PARSER// ═══════════════════════════════════════════════════════════════════════════/** * Parses a retail receipt (Big Bazaar, Reliance, Amazon delivery, etc.). * * ## Extraction Strategy * *  - **Merchant name**: First non-empty line OR "Merchant:" field *  - **Merchant address**: Line after merchant name (if contains digits/pin) *  - **Datetime**: First date + time found in text *  - **Items**: Lines matching "item name ... qty x price" or "item ... price" *  - **Subtotal**: Field RECEIPT_SUBTOTAL or text "Subtotal: ₹X" *  - **Tax (GST)**: Field INDIAN_CURRENCY after "GST" or "Tax" keyword *  - **Total**: Field RECEIPT_TOTAL or text "Total: ₹X" *  - **Payment method**: "Cash"/"Card"/"UPI" keyword search *  - **UPI ID**: Field INDIAN_UPI_ID (if present) */class ReceiptParser {    fun parse(fullText: String, fields: List<OcrField>): Receipt? {        if (fullText.isBlank()) return null        val lines = fullText.lines().map { it.trim() }.filter { it.isNotBlank() }        if (lines.isEmpty()) return null        Timber.tag(TAG).d("Parsing receipt: ${lines.size} lines, ${fields.size} fields.")        val merchantName = extractMerchantName(lines, fields)        val merchantAddress = extractMerchantAddress(lines)        val datetime = extractDatetime(fields, fullText)        val items = extractItems(lines)        val subtotal = extractSubtotal(fields, fullText)        val tax = extractTax(fields, fullText)        val total = extractTotal(fields, fullText)        val paymentMethod = extractPaymentMethod(fullText)        val upiId = fields.firstOrNull { it.type == OcrFieldType.INDIAN_UPI_ID }?.value        return Receipt(            merchantName = merchantName,            merchantAddress = merchantAddress,            datetime = datetime,            items = items,            subtotal = subtotal,            tax = tax,            total = total,            paymentMethod = paymentMethod,            upiId = upiId,        )    }    private fun extractMerchantName(lines: List<String>, fields: List<OcrField>): String? {        fields.firstOrNull { it.type == OcrFieldType.MERCHANT_NAME }?.let { return it.value }        // First non-empty line that's not a date/number.        return lines.firstOrNull { line ->            line.length in 2..60 &&            !line.matches(Regex(".*\\d{2,}.*")) &&  // Not mostly digits            !line.equals("receipt", ignoreCase = true) &&            !line.equals("invoice", ignoreCase = true)        }    }    private fun extractMerchantAddress(lines: List<String>): String? {        // Line after merchant that contains a pin code (6 digits) or street keywords.        for (i in 1 until lines.size) {            val line = lines[i]            if (line.contains(Regex("\\b\\d{6}\\b")) ||  // Indian pin code                line.contains("road", ignoreCase = true) ||                line.contains("street", ignoreCase = true) ||                line.contains("nagar", ignoreCase = true) ||                line.contains("colony", ignoreCase = true)) {                return line            }        }        return null    }    private fun extractDatetime(fields: List<OcrField>, text: String): String? {        val date = fields.firstOrNull { it.type == OcrFieldType.DATE }?.value        val time = fields.firstOrNull { it.type == OcrFieldType.TIME }?.value        return listOfNotNull(date, time).joinToString(" ").ifBlank { null }    }    private fun extractItems(lines: List<String>): List<ReceiptItem> {        val items = mutableListOf<ReceiptItem>()        // Pattern: "item name ... price" where price is at end of line.        val itemPattern = Regex("^(.+?)\\s+(?:₹?|Rs\\.?\\s?)?(\\d+(?:\\.\\d{1,2})?)$", RegexOption.IGNORE_CASE)        for (line in lines) {            // Skip lines that are clearly not items (totals, headers, dates).            if (line.contains(Regex("total|subtotal|gst|tax|cash|card|upi|date|time|receipt|invoice", RegexOption.IGNORE_CASE))) continue            val match = itemPattern.find(line)            if (match != null) {                val name = match.groupValues[1].trim()                val price = match.groupValues[2].toDoubleOrNull()                if (price != null && price > 0 && name.length in 2..50) {                    items.add(ReceiptItem(name = name, quantity = 1, price = price))                }            }        }        return items    }    private fun extractSubtotal(fields: List<OcrField>, text: String): Double? {        fields.firstOrNull { it.type == OcrFieldType.RECEIPT_SUBTOTAL }?.value?.toDoubleOrNull()?.let { return it }        Regex("(?:Sub\\s*total)[:\\s]*₹?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)", RegexOption.IGNORE_CASE).find(text)            ?.groupValues?.getOrNull(1)?.replace(",", "")?.toDoubleOrNull()?.let { return it }        return null    }    private fun extractTax(fields: List<OcrField>, text: String): Double? {        Regex("(?:GST|Tax)[:\\s]*₹?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)", RegexOption.IGNORE_CASE).find(text)            ?.groupValues?.getOrNull(1)?.replace(",", "")?.toDoubleOrNull()?.let { return it }        return null    }    private fun extractTotal(fields: List<OcrField>, text: String): Double? {        fields.firstOrNull { it.type == OcrFieldType.RECEIPT_TOTAL }?.value?.toDoubleOrNull()?.let { return it }        Regex("(?:Grand\\s*Total|Total|Amount\\s*Due)[:\\s]*₹?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)", RegexOption.IGNORE_CASE).find(text)            ?.groupValues?.getOrNull(1)?.replace(",", "")?.toDoubleOrNull()?.let { return it }        return null    }    private fun extractPaymentMethod(text: String): String? {        val lower = text.lowercase()        return when {            lower.contains("upi") || lower.contains("gpay") || lower.contains("phonepe") || lower.contains("paytm") -> "UPI"            lower.contains("card") -> "Card"            lower.contains("cash") -> "Cash"            lower.contains("wallet") -> "Wallet"            else -> null        }    }    private companion object {        private const val TAG = "ReceiptParser"    }}// ═══════════════════════════════════════════════════════════════════════════// 2. BUSINESS CARD PARSER// ═══════════════════════════════════════════════════════════════════════════/** * Parses a business card. * * ## Extraction Strategy * *  - **Name**: Field PERSON_NAME or first line (if not a company name) *  - **Title**: Text matching "Manager", "Director", "CEO", "Founder", etc. *  - **Organization**: Field ORGANIZATION or line containing "Inc.", "Ltd.", "Pvt Ltd" *  - **Phones**: All PHONE_NUMBER + INDIAN_PHONE fields *  - **Emails**: All EMAIL fields *  - **Address**: Field ADDRESS or line with pin code *  - **Website**: Field URL or line starting with "www." */class BusinessCardParser {    fun parse(fullText: String, fields: List<OcrField>): BusinessCard? {        if (fullText.isBlank()) return null        val lines = fullText.lines().map { it.trim() }.filter { it.isNotBlank() }        val personName = fields.firstOrNull { it.type == OcrFieldType.PERSON_NAME }?.value            ?: lines.firstOrNull { isLikelyPersonName(it) }        val jobTitle = extractJobTitle(fullText)        val organization = fields.firstOrNull { it.type == OcrFieldType.ORGANIZATION }?.value            ?: lines.firstOrNull { isLikelyOrganization(it) }        val phones = fields.filter { it.type == OcrFieldType.PHONE_NUMBER || it.type == OcrFieldType.INDIAN_PHONE }.map { it.value }        val emails = fields.filter { it.type == OcrFieldType.EMAIL }.map { it.value }        val address = lines.firstOrNull { it.contains(Regex("\\b\\d{6}\\b")) }        val website = fields.firstOrNull { it.type == OcrFieldType.URL }?.value            ?: lines.firstOrNull { it.startsWith("www.", ignoreCase = true) }        return BusinessCard(            personName = personName,            jobTitle = jobTitle,            organization = organization,            phoneNumbers = phones,            emails = emails,            address = address,            website = website,        )    }    private fun isLikelyPersonName(line: String): Boolean {        // 2-4 words, each starting with uppercase, no digits.        val words = line.split(" ")        if (words.size !in 1..4) return false        if (line.any { it.isDigit() }) return false        return words.all { it.firstOrNull()?.isUpperCase() == true }    }    private fun isLikelyOrganization(line: String): Boolean {        return line.contains(Regex("\\b(Inc\\.|Ltd\\.|Pvt\\.?\\s*Ltd\\.?|LLC|Corp\\.|Corporation|Company)\\b", RegexOption.IGNORE_CASE))    }    private fun extractJobTitle(text: String): String? {        val titleRegex = Regex("\\b(CEO|CTO|CFO|COO|CMO|Founder|Co-Founder|Director|Manager|Senior\\s+\\w+|Lead\\s+\\w+|\\w+\\s+(?:Engineer|Designer|Analyst|Consultant|Developer|Architect))\\b", RegexOption.IGNORE_CASE)        return titleRegex.find(text)?.value    }}// ═══════════════════════════════════════════════════════════════════════════// 3. GOVERNMENT ID PARSER (Aadhaar + PAN — masked per privacy)// ═══════════════════════════════════════════════════════════════════════════/** * Parses Indian government IDs (Aadhaar + PAN) with mandatory masking. * * ## Privacy (per strategy v3 §"Government ID auto-purge" + v4 §"Privacy") * *  - Aadhaar: ALWAYS masked as "XXXX-XXXX-1234" (only last 4 digits) *  - PAN: ALWAYS masked as "ABCDE***4F" (only first 5 + last char) *  - Raw image cryptographically shredded (DoD 5220.22-M) within 60s *  - Masked record stored in encrypted Memory (Module 3) — never synced * * ## Explicit Consent Required * * [parseAadhaar] and [parsePan] require [explicitConsentGranted]=true. * If false, returns null (no extraction performed). */class GovernmentIdParser {    /**     * Parse an Aadhaar card.     *     * @param fullText OCR text.     * @param fields extracted fields.     * @param explicitConsentGranted true if user explicitly consented (per-scan opt-in).     * @return masked [GovernmentId], or null if no consent or no Aadhaar found.     */    fun parseAadhaar(        fullText: String,        fields: List<OcrField>,        explicitConsentGranted: Boolean = false,    ): GovernmentId? {        if (!explicitConsentGranted) {            Timber.tag(TAG).w("Aadhaar parse requires explicit consent — returning null.")            return null        }        val aadhaarField = fields.firstOrNull { it.type == OcrFieldType.INDIAN_AADHAAR }            ?: return null  // No Aadhaar detected.        val rawAadhaar = aadhaarField.value        if (rawAadhaar.length != 12) {            Timber.tag(TAG).w("Aadhaar number not 12 digits — skipping.")            return null        }        val maskedNumber = maskAadhaar(rawAadhaar)        val name = extractAadhaarName(fullText, fields)        val dob = extractAadhaarDob(fullText)        val gender = extractAadhaarGender(fullText)        val address = extractAadhaarAddress(fullText)        Timber.tag(TAG).i("Aadhaar parsed (masked): $maskedNumber.")        return GovernmentId(            idType = GovernmentIdType.AADHAAR,            name = name ?: "Unknown",            maskedNumber = maskedNumber,            dateOfBirth = dob,            gender = gender,            address = address,            scanTimestamp = System.currentTimeMillis(),        )    }    /**     * Parse a PAN card.     *     * @param fullText OCR text.     * @param fields extracted fields.     * @param explicitConsentGranted true if user explicitly consented (per-scan opt-in).     * @return masked [GovernmentId], or null if no consent or no PAN found.     */    fun parsePan(        fullText: String,        fields: List<OcrField>,        explicitConsentGranted: Boolean = false,    ): GovernmentId? {        if (!explicitConsentGranted) {            Timber.tag(TAG).w("PAN parse requires explicit consent — returning null.")            return null        }        val panField = fields.firstOrNull { it.type == OcrFieldType.INDIAN_PAN }            ?: return null  // No PAN detected.        val rawPan = panField.value        if (!rawPan.matches(Regex("[A-Z]{5}\\d{4}[A-Z]"))) {            Timber.tag(TAG).w("PAN format invalid — skipping.")            return null        }        val maskedNumber = maskPan(rawPan)        val name = extractPanName(fullText, fields)        val dob = extractPanDob(fullText)        val fatherName = extractPanFatherName(fullText)        Timber.tag(TAG).i("PAN parsed (masked): $maskedNumber.")        return GovernmentId(            idType = GovernmentIdType.PAN,            name = name ?: "Unknown",            maskedNumber = maskedNumber,            dateOfBirth = dob,            gender = null,  // PAN doesn't have gender            address = fatherName?.let { "Father: $it" },            scanTimestamp = System.currentTimeMillis(),        )    }    /** Mask Aadhaar: "123456789012" → "XXXX-XXXX-9012". */    internal fun maskAadhaar(raw: String): String {        val last4 = raw.takeLast(4)        return "XXXX-XXXX-$last4"    }    /** Mask PAN: "ABCDE1234F" → "ABCDE***4F". */    internal fun maskPan(raw: String): String {        if (raw.length != 10) return "*****"        return raw.substring(0, 5) + "***" + raw.substring(8, 10)    }    private fun extractAadhaarName(text: String, fields: List<OcrField>): String? {        fields.firstOrNull { it.type == OcrFieldType.PERSON_NAME }?.let { return it.value }        // Fallback: text after "Name:" or first line.        Regex("(?:Name|नाम)[:\\s]+([A-Z][a-z]+(?:\\s+[A-Z][a-z]+){0,3})").find(text)?.groupValues?.getOrNull(1)?.let { return it }        return text.lines().firstOrNull { it.length in 3..50 && it.split(" ").size in 1..4 && it.firstOrNull()?.isUpperCase() == true }    }    private fun extractAadhaarDob(text: String): String? {        Regex("(?:DOB|Date of Birth)[:\\s]+(\\d{2}/\\d{2}/\\d{4})", RegexOption.IGNORE_CASE).find(text)?.groupValues?.getOrNull(1)?.let { return it }        Regex("\\b(\\d{2}/\\d{2}/\\d{4})\\b").find(text)?.groupValues?.getOrNull(1)?.let { return it }        return null    }    private fun extractAadhaarGender(text: String): String? {        val lower = text.lowercase()        return when {            lower.contains("male") && !lower.contains("female") -> "Male"            lower.contains("female") -> "Female"            else -> null        }    }    private fun extractAadhaarAddress(text: String): String? {        Regex(            "(?:Address|पता)[:\\s]+(.+?)(?:\\n|$)",            setOf(RegexOption.IGNORE_CASE, RegexOption.MULTILINE),        ).find(text)?.groupValues?.getOrNull(1)?.trim()?.let { return it }        return null    }    private fun extractPanName(text: String, fields: List<OcrField>): String? {        fields.firstOrNull { it.type == OcrFieldType.PERSON_NAME }?.let { return it.value }        // PAN cards typically have the name in uppercase.        return text.lines().firstOrNull { it.length in 3..50 && it == it.uppercase() && it.any(Char::isLetter) && !it.contains(Regex("\\d")) }    }    private fun extractPanDob(text: String): String? {        return Regex("\\b(\\d{2}/\\d{2}/\\d{4})\\b").find(text)?.groupValues?.getOrNull(1)    }    private fun extractPanFatherName(text: String): String? {        return Regex(            "(?:Father|Father's Name)[:\\s]+(.+?)(?:\\n|$)",            setOf(RegexOption.IGNORE_CASE, RegexOption.MULTILINE),        ).find(text)?.groupValues?.getOrNull(1)?.trim()    }    private companion object {        private const val TAG = "GovtIdParser"    }}// ═══════════════════════════════════════════════════════════════════════════// 4. INVOICE PARSER// ═══════════════════════════════════════════════════════════════════════════/** * Parses a vendor invoice. */class InvoiceParser {    fun parse(fullText: String, fields: List<OcrField>): Invoice? {        if (fullText.isBlank()) return null        val invoiceNumber = extractInvoiceNumber(fullText)        val vendorName = fields.firstOrNull { it.type == OcrFieldType.ORGANIZATION }?.value            ?: extractVendorName(fullText)        val vendorGstin = fields.firstOrNull { it.type == OcrFieldType.INDIAN_GSTIN }?.value        val invoiceDate = fields.firstOrNull { it.type == OcrFieldType.DATE }?.value        val dueDate = extractDueDate(fullText)        val lineItems = extractLineItems(fullText)        val subtotal = extractSubtotal(fullText)        val gst = extractGst(fullText)        val total = extractTotal(fullText)        return Invoice(            invoiceNumber = invoiceNumber,            vendorName = vendorName,            vendorGstin = vendorGstin,            invoiceDate = invoiceDate,            dueDate = dueDate,            lineItems = lineItems,            subtotal = subtotal,            gst = gst,            total = total,        )    }    private fun extractInvoiceNumber(text: String): String? {        return Regex("(?:Invoice|Inv)\\s*(?:No|Number|#)[:\\s]*([A-Z0-9\\-]+)", RegexOption.IGNORE_CASE).find(text)?.groupValues?.getOrNull(1)    }    private fun extractVendorName(text: String): String? {        // First line that's not an invoice number or date.        return text.lines().firstOrNull { line ->            line.length in 3..60 &&            !line.contains(Regex("invoice|tax|gst|date|amount|total", RegexOption.IGNORE_CASE)) &&            line.any(Char::isLetter)        }    }    private fun extractDueDate(text: String): String? {        return Regex("(?:Due\\s*Date|Payment\\s*Due)[:\\s]*(\\d{1,2}[/\\-]\\d{1,2}[/\\-]\\d{2,4})", RegexOption.IGNORE_CASE).find(text)?.groupValues?.getOrNull(1)    }    private fun extractLineItems(text: String): List<ReceiptItem> {        // Reuse receipt item extraction logic.        return ReceiptParser().run {            val lines = text.lines().map { it.trim() }.filter { it.isNotBlank() }            lines.filter { line ->                !line.contains(Regex("total|subtotal|gst|tax|invoice|date|due", RegexOption.IGNORE_CASE))            }.mapNotNull { line ->                val match = Regex("^(.+?)\\s+(?:₹?|Rs\\.?\\s?)?(\\d+(?:\\.\\d{1,2})?)$").find(line)                match?.let {                    val name = it.groupValues[1].trim()                    val price = it.groupValues[2].toDoubleOrNull()                    if (price != null && price > 0 && name.length in 2..50) {                        ReceiptItem(name = name, quantity = 1, price = price)                    } else null                }            }        }    }    private fun extractSubtotal(text: String): Double? {        return Regex("(?:Sub\\s*total)[:\\s]*₹?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)", RegexOption.IGNORE_CASE).find(text)?.groupValues?.getOrNull(1)?.replace(",", "")?.toDoubleOrNull()    }    private fun extractGst(text: String): Double? {        return Regex("(?:GST|Tax)[:\\s]*₹?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)", RegexOption.IGNORE_CASE).find(text)?.groupValues?.getOrNull(1)?.replace(",", "")?.toDoubleOrNull()    }    private fun extractTotal(text: String): Double? {        return Regex("(?:Grand\\s*Total|Total|Amount\\s*Due)[:\\s]*₹?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d{1,2})?)", RegexOption.IGNORE_CASE).find(text)?.groupValues?.getOrNull(1)?.replace(",", "")?.toDoubleOrNull()    }}// ═══════════════════════════════════════════════════════════════════════════// 5. UNIFIED DOCUMENT PARSER (dispatches based on DocumentType)// ═══════════════════════════════════════════════════════════════════════════/** * Unified parser dispatcher — replaces the stub [com.roshan.persona.vision.ocr.StructuredDocumentParser]. * * Routes to the appropriate parser based on [com.roshan.persona.vision.ocr.DocumentType]. */class UnifiedDocumentParser(    private val receiptParser: ReceiptParser = ReceiptParser(),    private val prescriptionScanner: PrescriptionScanner = PrescriptionScanner(),    private val businessCardParser: BusinessCardParser = BusinessCardParser(),    private val governmentIdParser: GovernmentIdParser = GovernmentIdParser(),    private val invoiceParser: InvoiceParser = InvoiceParser(),    private val handwrittenNoteParser: HandwrittenNoteParser = HandwrittenNoteParser(),) {    fun parse(        documentType: com.roshan.persona.vision.ocr.DocumentType,        fullText: String,        extractedFields: List<OcrField>,        blocks: List<OcrBlock>,        explicitGovIdConsent: Boolean = false,    ): StructuredDocument? {        return when (documentType) {            com.roshan.persona.vision.ocr.DocumentType.RECEIPT -> receiptParser.parse(fullText, extractedFields)            com.roshan.persona.vision.ocr.DocumentType.PRESCRIPTION -> prescriptionScanner.parse(fullText, extractedFields, blocks)            com.roshan.persona.vision.ocr.DocumentType.BUSINESS_CARD -> businessCardParser.parse(fullText, extractedFields)            com.roshan.persona.vision.ocr.DocumentType.AADHAAR_CARD -> governmentIdParser.parseAadhaar(fullText, extractedFields, explicitGovIdConsent)            com.roshan.persona.vision.ocr.DocumentType.PAN_CARD -> governmentIdParser.parsePan(fullText, extractedFields, explicitGovIdConsent)            com.roshan.persona.vision.ocr.DocumentType.INVOICE -> invoiceParser.parse(fullText, extractedFields)            com.roshan.persona.vision.ocr.DocumentType.HANDWRITTEN_NOTE -> handwrittenNoteParser.parse(fullText, blocks)            else -> null        }    }}/** Handwritten note parser (from Step 6.2 — moved here for organization). */class HandwrittenNoteParser {    fun parse(fullText: String, blocks: List<OcrBlock>): com.roshan.persona.vision.ocr.HandwrittenNote? {        val detectedLanguage = blocks.firstOrNull()?.recognizedLanguage        return com.roshan.persona.vision.ocr.HandwrittenNote(text = fullText, detectedLanguage = detectedLanguage)    }}